                                       pm_power_module_state_e power_state)
{
  bool enable;

  if (power_state == PM_POWER_MODULE_STATE_ON)
    {
      enable = true;
    }
  else if (power_state == PM_POWER_MODULE_STATE_OFF)
    {
      enable = false;
