  if (module == PM_POWER_MODULE_NAME_WIFIP_MAC)
    {
      return bk7258_mac_power(enable) == OK ? BK_OK : BK_FAIL;
    }
  else if (module == PM_POWER_MODULE_NAME_PHY)
    {
      return bk7258_phy_power(enable) == OK ? BK_OK : BK_FAIL;
    }

  return BK_ERR_NOT_SUPPORT;
}

