  up_udelay(200);
  t2 = getreg32(0x49100010);
  ac = getreg32(0x491000ac);

  syslog(LOG_INFO, "[BK7258-WIFI] d3f tick=%08lx->%08lx ac=%08lx\n",
         (unsigned long)t1, (unsigned long)t2, (unsigned long)ac);
}

